export function stringHasCharacters(value) {
    return value != null && value.trim().length > 0;
}
// getIdSafeString is used in the following files:
// src/cdn-assets/web-components/file-picker/neon-file-picker.ts
// its purpose is to take a File.name and return a string that can be used as an id
// for internal use
export function getIdSafeString(string) {
    // trim whitespace
    let validId = String(string).trim();
    // Replace spaces and non-alphanumeric characters with underscores
    validId = validId.replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '_');
    // Ensure the ID starts with a letter (prepend 'id_' if not)
    if (!/^[a-zA-Z]/.test(validId)) {
        validId = 'id_' + validId;
    }
    return validId;
}
